import{_ as e,o as s,c as n,ag as t}from"./chunks/framework.DoUXNnsN.js";const g=JSON.parse('{"title":"Git分支与合并","description":"","frontmatter":{"title":"Git分支与合并","aliases":["git branch","git switch","git merge","git rebase","分支","Fast-forward","快进合并"],"tags":["工具与工程","Git"],"status":"ai-draft","sources":["https://git-scm.com/book/zh/v2/Git-分支-分支简介","https://git-scm.com/docs/git-rebase","基于模型知识"],"updated":"2026-10-21T00:00:00.000Z","order":3},"headers":[],"relativePath":"50-工具与工程/Git/Git分支与合并.md","filePath":"50-工具与工程/Git/Git分支与合并.md"}'),i={name:"50-工具与工程/Git/Git分支与合并.md"};function o(p,a,l,c,r,d){return s(),n("div",null,[...a[0]||(a[0]=[t(`<blockquote><p>本篇是 <a href="/Encyclopedia/50-工具与工程/Git/Git">Git</a> 入门路径的第 3 篇。读完你应该能：解释分支到底是什么；创建、切换、删除分支；区分快进合并和三方合并；知道 rebase 做了什么、什么时候不能用。</p><p>命令在 Windows 11 + Git for Windows 2.54.0（Git Bash）里实际运行，哈希每次不同。为易读，提交说明故意写成 <code>C1</code>、<code>F1</code> 这类编号。</p></blockquote><h2 id="一句话定义" tabindex="-1">一句话定义 <a class="header-anchor" href="#一句话定义" aria-label="Permalink to &quot;一句话定义&quot;">​</a></h2><p><strong>分支</strong>是指向某个 commit 的可移动标签，让你在不影响主线的情况下并行开发；<strong>合并</strong>（merge）把一条分支的成果汇入另一条；<strong>变基</strong>（rebase）则是把一串提交&quot;搬&quot;到另一个起点上重放。</p><h2 id="先修知识" tabindex="-1">先修知识 <a class="header-anchor" href="#先修知识" aria-label="Permalink to &quot;先修知识&quot;">​</a></h2><ul><li><a href="/Encyclopedia/50-工具与工程/Git/Git基础操作">Git基础操作</a>：会 add、commit、log。</li><li><a href="/Encyclopedia/50-工具与工程/Git/Git">Git</a>：知道 commit 通过父指针串成链，HEAD 表示当前位置。</li></ul><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>主线 <code>main</code> 上放的是&quot;能跑的版本&quot;。你要开发新功能（比如登录），需要几天，期间不能把半成品放在主线上，也不想因为别人在主线上改东西而影响自己。分支让每件事各走各的路，做完再汇合。</p><p>在 <a href="/Encyclopedia/50-工具与工程/Git/Git工作流">Git工作流</a> 里，几乎所有团队约定都是建立在分支之上的。</p><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><h3 id="分支只是一个指针" tabindex="-1">分支只是一个指针 <a class="header-anchor" href="#分支只是一个指针" aria-label="Permalink to &quot;分支只是一个指针&quot;">​</a></h3><p>想象 commit 是一串珠子，分支是挂在某颗珠子上的小纸条，写着名字。创建分支 = 多贴一张纸条，不复制任何文件，所以瞬间完成。HEAD 是&quot;你的手指&quot;，指着当前纸条。提交时，当前纸条自动往前挪到新珠子上。</p><h3 id="常用命令" tabindex="-1">常用命令 <a class="header-anchor" href="#常用命令" aria-label="Permalink to &quot;常用命令&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>git branch</code></td><td>列出本地分支，<code>*</code> 标出当前分支</td></tr><tr><td><code>git branch 名字</code></td><td>创建分支（不切换）</td></tr><tr><td><code>git switch 名字</code></td><td>切换到分支</td></tr><tr><td><code>git switch -c 名字</code></td><td>创建并切换</td></tr><tr><td><code>git branch -d 名字</code></td><td>删除已合并的分支</td></tr><tr><td><code>git branch -D 名字</code></td><td>强制删除（即使未合并）</td></tr><tr><td><code>git merge 名字</code></td><td>把该分支合并进<strong>当前</strong>分支</td></tr><tr><td><code>git rebase 名字</code></td><td>把当前分支的提交重放到该分支顶端</td></tr><tr><td><code>git log --oneline --graph --all</code></td><td>画出所有分支的提交图</td></tr></tbody></table><p><code>git switch</code> 是较新的命令（Git 2.23 起），老教程常用 <code>git checkout 名字</code>，作用等价。</p><h3 id="两种合并" tabindex="-1">两种合并 <a class="header-anchor" href="#两种合并" aria-label="Permalink to &quot;两种合并&quot;">​</a></h3><ol><li><strong>快进合并</strong>（Fast-forward）：当前分支自分叉以来没有新提交，直接把标签往前挪，历史是一条直线，不产生新提交。</li><li><strong>三方合并</strong>（three-way merge）：双方都有新提交，Git 找到共同祖先，把两边的改动合在一起，生成一个有<strong>两个父提交</strong>的合并提交（merge commit）。</li></ol><h2 id="逐步例子" tabindex="-1">逐步例子 <a class="header-anchor" href="#逐步例子" aria-label="Permalink to &quot;逐步例子&quot;">​</a></h2><h3 id="例-1-开分支-快进合并" tabindex="-1">例 1：开分支 -&gt; 快进合并 <a class="header-anchor" href="#例-1-开分支-快进合并" aria-label="Permalink to &quot;例 1：开分支 -&gt; 快进合并&quot;">​</a></h3><p>起点：<code>main</code> 上已有两个提交 C1、C2。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git branch</span></span>
<span class="line"><span>* main</span></span>
<span class="line"><span>$ git switch -c feature-login</span></span>
<span class="line"><span>Switched to a new branch &#39;feature-login&#39;</span></span></code></pre></div><p>在分支上做两次提交 F1、F2：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git branch -v</span></span>
<span class="line"><span>* feature-login 1af461d F2: login ok</span></span>
<span class="line"><span>  main          7e919f6 C2: app v2</span></span>
<span class="line"><span>$ git log --oneline --graph --all</span></span>
<span class="line"><span>* 1af461d F2: login ok</span></span>
<span class="line"><span>* 3ca9c85 F1: add login</span></span>
<span class="line"><span>* 7e919f6 C2: app v2</span></span>
<span class="line"><span>* 739d3c3 C1: app v1</span></span></code></pre></div><p><code>-v</code> 显示每个分支指向哪个提交：<code>main</code> 还停在 C2，<code>feature-login</code> 前进了两步。切回 main，注意工作区里<strong>没有 <code>login.txt</code></strong>（<code>ls</code> 只有 <code>app.txt</code>），因为 main 的快照里没有它——切换分支会让工作区变成该分支的样子。然后合并：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git switch main</span></span>
<span class="line"><span>Switched to branch &#39;main&#39;</span></span>
<span class="line"><span>$ ls</span></span>
<span class="line"><span>app.txt</span></span>
<span class="line"><span>$ git merge feature-login</span></span>
<span class="line"><span>Updating 7e919f6..1af461d</span></span>
<span class="line"><span>Fast-forward</span></span>
<span class="line"><span> login.txt | 2 ++</span></span>
<span class="line"><span> 1 file changed, 2 insertions(+)</span></span>
<span class="line"><span> create mode 100644 login.txt</span></span></code></pre></div><p><code>Fast-forward</code> 就是 main 的标签直接移到 <code>1af461d</code>，没有新提交。</p><h3 id="例-2-三方合并" tabindex="-1">例 2：三方合并 <a class="header-anchor" href="#例-2-三方合并" aria-label="Permalink to &quot;例 2：三方合并&quot;">​</a></h3><p>新建 <code>feature-report</code> 分支提交 R1（加 <code>report.txt</code>），然后<strong>回到 main 再提交 C3</strong>（改 <code>app.txt</code>），这样两边都有新提交：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git merge feature-report -m &quot;Merge feature-report&quot;</span></span>
<span class="line"><span>Merge made by the &#39;ort&#39; strategy.</span></span>
<span class="line"><span> report.txt | 1 +</span></span>
<span class="line"><span> 1 file changed, 1 insertion(+)</span></span>
<span class="line"><span> create mode 100644 report.txt</span></span>
<span class="line"><span>$ git log --oneline --graph --all</span></span>
<span class="line"><span>*   a754ce7 Merge feature-report</span></span>
<span class="line"><span>|\\</span></span>
<span class="line"><span>| * f6286a7 R1: add report</span></span>
<span class="line"><span>* | a37855f C3: app v3</span></span>
<span class="line"><span>|/</span></span>
<span class="line"><span>* 1af461d F2: login ok</span></span>
<span class="line"><span>* 3ca9c85 F1: add login</span></span>
<span class="line"><span>* 7e919f6 C2: app v2</span></span>
<span class="line"><span>* 739d3c3 C1: app v1</span></span></code></pre></div><p>图里分叉又汇合：<code>a754ce7</code> 是合并提交，有两个父提交（<code>a37855f</code> 与 <code>f6286a7</code>）。<code>ort</code> 是 Git 默认的合并算法名，不用管。两边改的是不同文件，所以自动合并成功；如果改了同一处，会产生冲突，见 <a href="/Encyclopedia/50-工具与工程/Git/Git冲突与撤销">Git冲突与撤销</a>。</p><p>合并完的分支可以删掉（只是删标签，提交都在 main 的历史里）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git branch -d feature-login feature-report</span></span>
<span class="line"><span>Deleted branch feature-login (was 1af461d).</span></span>
<span class="line"><span>Deleted branch feature-report (was f6286a7).</span></span></code></pre></div><h3 id="例-3-rebase" tabindex="-1">例 3：rebase <a class="header-anchor" href="#例-3-rebase" aria-label="Permalink to &quot;例 3：rebase&quot;">​</a></h3><p>场景：从 main 拉出 <code>feature-x</code> 提交了 X1，同时 main 自己前进了 C4。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git log --oneline --graph --all</span></span>
<span class="line"><span>* a468d53 X1: add x</span></span>
<span class="line"><span>| * ae1a220 C4: app v4</span></span>
<span class="line"><span>|/</span></span>
<span class="line"><span>*   a754ce7 Merge feature-report</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>不想产生合并提交，想让历史成一条直线，就在 <code>feature-x</code> 上 rebase：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git switch feature-x</span></span>
<span class="line"><span>$ git rebase main</span></span>
<span class="line"><span>Rebasing (1/1)Successfully rebased and updated refs/heads/feature-x.</span></span>
<span class="line"><span>$ git log --oneline --graph --all</span></span>
<span class="line"><span>* 642577d X1: add x</span></span>
<span class="line"><span>* ae1a220 C4: app v4</span></span>
<span class="line"><span>*   a754ce7 Merge feature-report</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>对比：<strong>X1 的哈希从 <code>a468d53</code> 变成了 <code>642577d</code></strong>。rebase 其实是把 X1 的改动在 C4 之后&quot;重新做一遍&quot;，生成了一个新提交，旧的被丢弃。现在 <code>feature-x</code> 在 main 正前方，回 main 合并就是快进：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git switch main</span></span>
<span class="line"><span>$ git merge feature-x</span></span>
<span class="line"><span>Updating ae1a220..642577d</span></span>
<span class="line"><span>Fast-forward</span></span>
<span class="line"><span> x.txt | 1 +</span></span>
<span class="line"><span> 1 file changed, 1 insertion(+)</span></span>
<span class="line"><span> create mode 100644 x.txt</span></span></code></pre></div><h3 id="merge-还是-rebase" tabindex="-1">merge 还是 rebase？ <a class="header-anchor" href="#merge-还是-rebase" aria-label="Permalink to &quot;merge 还是 rebase？&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>merge</th><th>rebase</th></tr></thead><tbody><tr><td>历史</td><td>保留真实的分叉与汇合，有合并提交</td><td>一条直线，更整洁</td></tr><tr><td>本质</td><td>不改已有提交</td><td><strong>重写提交</strong>（新哈希）</td></tr><tr><td>风险</td><td>低</td><td>已经 push 给别人的提交不要 rebase</td></tr></tbody></table><p>黄金规则：<strong>只对还没推送（push）的、只有你自己用的提交做 rebase</strong>。已经共享的提交被改写，同事的历史就和你对不上，会引发混乱。拿不准就用 merge。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ol><li><code>git init -b main</code>，提交 <code>a.txt</code>（内容 <code>1</code>）为 C1。</li><li><code>git switch -c exp</code>，追加一行到 a.txt 并提交。</li><li><code>git switch main</code>，<code>cat a.txt</code>（PowerShell 用 <code>Get-Content a.txt</code>），确认还是一行，说明切换分支改变了工作区。</li><li><code>git merge exp</code>，应看到 <code>Fast-forward</code>，<code>cat a.txt</code> 变成两行。</li><li>再来一轮：<code>git switch -c exp2</code> 提交一个新文件；回 <code>main</code> 修改 a.txt 再提交；<code>git merge exp2 -m &quot;Merge exp2&quot;</code>，应看到 <code>Merge made by the &#39;ort&#39; strategy</code>；用 <code>git log --oneline --graph</code> 看到分叉汇合图。</li><li>删除分支：<code>git branch -d exp exp2</code>。</li></ol><h2 id="常见坑与排查" tabindex="-1">常见坑与排查 <a class="header-anchor" href="#常见坑与排查" aria-label="Permalink to &quot;常见坑与排查&quot;">​</a></h2><ul><li><strong>切换分支时提示 <code>Your local changes would be overwritten</code></strong>：工作区有未提交改动，且与目标分支冲突。先 commit，或用 <code>git stash</code> 暂存（见 <a href="/Encyclopedia/50-工具与工程/Git/Git冲突与撤销">Git冲突与撤销</a>）。</li><li><strong><code>git branch -d</code> 拒绝删除</strong>：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git branch -d tmp-b</span></span>
<span class="line"><span>error: the branch &#39;tmp-b&#39; is not fully merged</span></span>
<span class="line"><span>hint: If you are sure you want to delete it, run &#39;git branch -D tmp-b&#39;</span></span></code></pre></div><p>意思是这个分支上有 main 没有的提交，删掉会丢工作。确认不要才用 <code>-D</code>。就算误删，也能用 reflog 找回，见 <a href="/Encyclopedia/50-工具与工程/Git/Git冲突与撤销">Git冲突与撤销</a>。</p><ul><li><strong>忘了自己在哪个分支就开始提交</strong>：先 <code>git branch</code> 或看终端提示符，养成习惯。</li><li><strong>合并方向搞反</strong>：<code>git merge X</code> 是&quot;把 X 合进<strong>当前</strong>分支&quot;，先 <code>switch</code> 到接收方。</li><li><strong>对共享分支 rebase 后 push 被拒</strong>：这是预期的保护，不要用强制推送硬顶，先和同事沟通。</li></ul><h2 id="练习题与答案" tabindex="-1">练习题与答案 <a class="header-anchor" href="#练习题与答案" aria-label="Permalink to &quot;练习题与答案&quot;">​</a></h2><p><strong>1.</strong> 创建分支会复制整个项目吗？ 答：不会，只是新建一个指向当前 commit 的指针。</p><p><strong>2.</strong> 什么情况下 <code>git merge</code> 会是 Fast-forward？ 答：被合并的分支是当前分支的&quot;直接后代&quot;，即当前分支自分叉后没有新提交。</p><p><strong>3.</strong> 合并提交和普通提交最大的区别？ 答：它有两个（或更多）父提交。</p><p><strong>4.</strong> 为什么 rebase 之后提交的哈希变了？ 答：哈希由提交内容（包括父提交）算出；父提交变了，新提交就是另一个对象，旧的被丢弃。</p><p><strong>5.</strong> 同事已经 <code>pull</code> 了你的分支，你还能放心 rebase 它吗？ 答：不能。会重写他已有的历史。应该用 merge。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>分支 = 轻量指针；切换分支会改变工作区内容。</li><li>无分叉 -&gt; 快进合并；有分叉 -&gt; 三方合并，生成两个父提交的合并提交。</li><li>rebase 重放提交以获得线性历史，会改变哈希；已共享的提交不要 rebase。</li></ul><h2 id="相关词条" tabindex="-1">相关词条 <a class="header-anchor" href="#相关词条" aria-label="Permalink to &quot;相关词条&quot;">​</a></h2><p><a href="/Encyclopedia/50-工具与工程/Git/Git">Git</a>、<a href="/Encyclopedia/50-工具与工程/Git/Git基础操作">Git基础操作</a>、<a href="/Encyclopedia/50-工具与工程/Git/Git冲突与撤销">Git冲突与撤销</a>、<a href="/Encyclopedia/50-工具与工程/Git/Git远程仓库">Git远程仓库</a>、<a href="/Encyclopedia/50-工具与工程/Git/Git工作流">Git工作流</a></p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li>Pro Git 分支简介：<a href="https://git-scm.com/book/zh/v2/Git-%E5%88%86%E6%94%AF-%E5%88%86%E6%94%AF%E7%AE%80%E4%BB%8B" target="_blank" rel="noreferrer">https://git-scm.com/book/zh/v2/Git-分支-分支简介</a></li><li>git rebase 文档：<a href="https://git-scm.com/docs/git-rebase" target="_blank" rel="noreferrer">https://git-scm.com/docs/git-rebase</a></li><li>Learn Git Branching（可视化交互教程）：<a href="https://learngitbranching.js.org/?locale=zh_CN" target="_blank" rel="noreferrer">https://learngitbranching.js.org/?locale=zh_CN</a></li></ul>`,60)])])}const b=e(i,[["render",o]]);export{g as __pageData,b as default};
